            Expect.Do("dense, no gaps", () => { Expect.Seq("dense, no gaps", Ranking.RankTransform(new[] { 37, 12, 28, 9, 100, 56, 80, 5, 12 }), 5, 3, 4, 2, 8, 6, 7, 1, 3); });
        } catch (Exception e) { Expect.Setup(e); }
        Expect.Summary(5);
    }
